/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/shared/gameplay/entities/00297d10.c, FUN_L06_002e94f0. */
void update_frog_health_respawn_and_target(struct Moby *moby) {
    struct FrogVars *vars;
    struct MobyHit *hit;
    int kind;
    float damage;
    int code;

    vars = (struct FrogVars *)moby->pvars;
    vars->spin = moby->rot_row2.z * 0.25f;
    if (vars->carried != 0) {
        hit = MobyGetHitMessage_r2(vars->carried, 0x330000, 0);
        if (hit != 0 && (hit->source == 0 || hit->source->oclass != 0xAF)) {
            spawn_moby_directional_spark_bursts_r(moby, (Vec4 *)blarg_zero_vec);
            destroy_frog_child_moby_r(moby);
            SetDeathBits(moby, 0, -1);
            goto remove;
        }
    }
    damage = 0.0f;
    hit = MobyGetHitMessage_r2(moby, 0x330000, 0);
    code = ComputeHitResponse(moby, hit, &vars->health, 0, &kind, &damage, 0, 4);
    if (kind != 1 && moby->state != 0xE) {
        vars->health = vars->health - damage;
        if (vars->health <= 0.0f) {
            code = 1;
        }
        switch (code) {
        case 1:
        case 2:
            SetDeathBits(moby, 0, -1);
            spawn_moby_directional_spark_bursts_r(moby, (Vec4 *)&hit->pos);
            if (vars->sparks_pending == 1) {
                spawn_moby_death_effect_burst((char *)moby);
                vars->sparks_pending = 0;
            }
            Moby_PlaySound(3, 0, (int)moby);
            if (vars->carried != 0) {
                destroy_frog_child_moby_r(moby);
            }
            if (vars->lives == 0) {
            remove:
                DeleteMoby_r(moby);
                return;
            }
            vars->lives = vars->lives - 1;
            vars->health = vars->max_health;
            qcopy(&moby->pos, &vars->spawn_pos);
            moby->state = 0xF;
            moby->collision = 0;
            moby->flags = (moby->flags & 0xEFFF) | 0x41;
            break;
        case 0:
        case 3:
        case 11:
            break;
        }
    }
    moby->hit_slot = 0xFF;
    vars->glow_phase = FastAddRots(vars->glow_phase, (*(f32 *)&frog_glow_phase_rate_degrees_gp) * 0.017453292f * g_frame_time);
    moby->glow_color = FastTweenColor((*(int *)&frog_glow_color_start_gp), (*(int *)&frog_glow_color_end_gp), (FastSin(vars->glow_phase) + 1.0f) * 0.5f);
    if (vars->new_blink != 0) {
        vars->blink_timer = truncate_float_to_s32(multiply_global_factor(random_float_between(180.0f, 240.0f)));
        vars->new_blink = 0;
    }
    FastDecTimer(&vars->blink_timer);
    if (vars->blink_timer != 0) {
        vars->range = vars->base_range + 6.0f;
    } else {
        vars->range = vars->base_range;
    }
    if (vars->target_id != -1) {
        struct Moby *target = &(*(struct Moby * *)&level_mobys_q_r)[vars->target_id];
        vars->target_mode = 1;
        vars->target = target;
        qcopy(&vars->target_pos, &target->pos);
    } else if (hero_vehicle_mode[0] == 1) {
        if (blarg_frame_count % 8 == vars->frame_slot) {
            select_hero_or_gadgebot_target((char *)moby, (char **)&vars->target, vars->range);
            if (vars->target == 0) {
                vars->target_mode = 2;
            } else {
                int *path = blarg_paths[vars->path];
                if (IsPointInPolygon(&vars->target->pos, path + 4, *path) == 0 ||
                    (vars->target->oclass == 0x359 && 2.0f < vec_distance_xy(&moby->pos, &vars->target->pos))) {
                    vars->target = 0;
                    vars->target_mode = 2;
                } else {
                    vars->target_mode = 0;
                }
            }
        }
    } else {
        Vec4f *goal = &vars->target_pos;
        int *path = blarg_paths[vars->path];
        if (FindNearestEligibleMoby(moby, goal, vars->range, 0, 0, path + 4, *path) != 2) {
            if (vars->range < vec_distance_xy(&vars->spawn_pos, goal) ||
                3.0f < FastAbsF(moby->pos.z - vars->target_pos.z)) {
                vars->target_mode = 2;
            }
        }
    }
    if (vars->target == 0) {
        vars->target = g_hero_moby_r;
    }
}
