// builds two offset vectors from the moby position and calls func_L00_001EFFF0 with them
void probe_frog_local_z_collision(char *moby) {
    float a[4];
    float b[4];
    float c[4];
    qcopy(b, &((Moby *)moby)->pos);
    vec_scale_to_length(c, &((Moby *)moby)->rot_row2, 1.0f);
    FastVecAdd(b, b, c);
    qcopy(a, &((Moby *)moby)->pos);
    vec_scale_to_length(c, &((Moby *)moby)->rot_row2, -1.0f);
    FastVecAdd(a, a, c);
    coll_line(b, a, 2, 0, 0);
}
