void update_gadgebot_glow_effects(char *obj)
{
    char *d;
    int tint;
    int i;
    f32 f20;
    int r, g, b, a;

    if (((Moby *)obj)->group == 0xFF) {
        return;
    }
    d = ((char *)((Moby *)obj)->pvars);
    tint = 0x3228AAAA;
    if (((Moby *)obj)->state == 3 || ((Moby *)obj)->state == 6) {
        tint = 0x3228AA28;
    } else if (((Moby *)obj)->state == 5 || ((Moby *)obj)->state == 9) {
        tint = 0x322828AA;
    } else if (((Moby *)obj)->state == 7) {
        tint = 0x32AA2828;
    }

    *(f32 *)(d + 0x28C) = FastAddRots(*(f32 *)(d + 0x28C), g_frame_time * 2.9670596f);
    f20 = 0.5f * FastSin(*(f32 *)(d + 0x28C)) + 1.0f;

    r = tint & 0xFF;
    b = (tint >> 16) & 0xFF;
    g = (tint >> 8) & 0xFF;
    a = ((unsigned int)tint) >> 24;

    r = truncate_float_to_s32((f32)r * f20);
    if (r >= 0x100) r = 0xFF;
    g = truncate_float_to_s32((f32)g * f20);
    if (g >= 0x100) g = 0xFF;
    b = truncate_float_to_s32((f32)b * f20);
    if (b >= 0x100) b = 0xFF;

    {
        int packed = a << 24;
        packed |= b << 16;
        packed |= g << 8;
        packed |= r;
        ((Moby *)obj)->glow_color = FastTweenColor(((Moby *)obj)->glow_color, packed, 0.1f);
    }

    for (i = 0; i < 3; i++) {
        Moby_GetJointWorldPos(obj, i + 1, d + 0x140 + i * 0x10);
    }
    {
        int dv = blarg_frame_count;
        *(int *)(d + 0x290) = ((Moby *)obj)->glow_color;
        if (dv != 0) {
        int *p = *(int **)(d + 0x294);
        if (dv != *p) {
            *p = dv;
            AddDrawCallback_r(draw_gadgebot_group_glow_effects_r, obj);
        }
        }
    }
}

